class Solution:
    def drawLine(self, length: int, w: int, x1: int, x2: int, y: int) -> List[int]:
        res = [0] * length
        per_row = w // 32
        for x in range(x1, x2 + 1):
            group = y * per_row + x // 32
            bit = 31 - (x % 32)
            res[group] |= 1 << bit
            if res[group] >= 2 ** 31:
                res[group] -= 2 ** 32
        return res

impl Solution {
  pub fn draw_line(length: i32, w: i32, x1: i32, x2: i32, y: i32) -> Vec<i32> {
    let mut res = vec![0i32; length as usize];
    let per_row = w / 32;
    for x in x1..=x2 {
      let group = (y * per_row + x / 32) as usize;
      let bit = 31 - (x % 32);
      res[group] |= 1i32 << bit;
    }
    res
  }
}

const drawLine = (length: number, w: number, x1: number, x2: number, y: number): number[] => {
  const res: number[] = new Array(length).fill(0);
  const perRow = Math.floor(w / 32);
  for (let x = x1; x <= x2; x++) {
    const group = y * perRow + Math.floor(x / 32);
    const bit = 31 - (x % 32);
    res[group] = res[group] | (1 << bit);
  }
  return res;
};
